import os
import unicodedata
import hashlib
import hmac
import re
from pathlib import PurePosixPath

SECRET_KEY = os.urandom(32)
BASE_DIR = '/var/app/documents'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.doc', '.png', '.jpg'}


def generate_access_token(username: str, resource_path: str) -> str:
    """Generate HMAC token for authorized resource access."""
    msg = f"{username}:{resource_path}".encode('utf-8')
    return hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()


def verify_access_token(username: str, resource_path: str, token: str) -> bool:
    """Verify HMAC token with constant-time comparison."""
    expected = generate_access_token(username, resource_path)
    return hmac.compare_digest(expected, token)


def sanitize_filename(filename: str) -> str:
    """Remove null bytes and control characters from filename."""
    # Strip null bytes
    filename = filename.replace('\x00', '')
    # Strip control characters (0x00-0x1f, 0x7f)
    filename = re.sub(r'[\x00-\x1f\x7f]', '', filename)
    return filename


def check_path_traversal(filepath: str) -> bool:
    """Check if path contains traversal sequences. Returns True if SAFE."""
    # Check for obvious traversal patterns
    if '..' in filepath:
        return False
    if filepath.startswith('/'):
        return False
    if '~' in filepath:
        return False
    # Check each component
    parts = filepath.split('/')
    for part in parts:
        if part in ('.', '..', ''):
            return False
    return True


def validate_extension(filepath: str) -> bool:
    """Ensure file has an allowed extension."""
    _, ext = os.path.splitext(filepath)
    return ext.lower() in ALLOWED_EXTENSIONS


def normalize_unicode(text: str) -> str:
    """Normalize unicode to canonical form for consistent storage.

    Uses NFKC normalization to handle compatibility equivalences,
    ensuring that visually similar characters map to the same codepoint.
    This prevents duplicate filenames that look identical but differ
    in unicode representation.
    """
    return unicodedata.normalize('NFKC', text)


def resolve_document_path(user_input: str) -> str:
    """Safely resolve a user-provided filename to an absolute path.

    Security measures:
    1. Sanitize control characters and null bytes
    2. Validate no path traversal sequences
    3. Validate file extension
    4. Normalize unicode for consistent storage
    5. Resolve against base directory
    """
    # Step 1: Sanitize
    cleaned = sanitize_filename(user_input)

    if not cleaned:
        raise ValueError("Empty filename after sanitization")

    # Step 2: Check for path traversal on the cleaned input
    if not check_path_traversal(cleaned):
        raise ValueError("Path traversal detected")

    # Step 3: Validate extension
    if not validate_extension(cleaned):
        raise ValueError("File extension not allowed")

    # Step 4: Normalize unicode AFTER security checks
    # This ensures consistent filename storage across platforms
    normalized = normalize_unicode(cleaned)

    # Step 5: Construct final path
    final_path = os.path.join(BASE_DIR, normalized)

    return final_path


def read_document(username: str, filename: str, token: str) -> bytes:
    """Read a document with access control verification."""
    try:
        resolved = resolve_document_path(filename)
    except ValueError as e:
        return b'ERROR: ' + str(e).encode()

    # Verify token against the resolved path
    relative = os.path.relpath(resolved, BASE_DIR)
    if not verify_access_token(username, relative, token):
        return b'ERROR: Access denied'

    if not os.path.isfile(resolved):
        return b'ERROR: File not found'

    with open(resolved, 'rb') as f:
        return f.read()


def write_document(username: str, filename: str, content: bytes, token: str) -> bool:
    """Write a document with access control verification."""
    try:
        resolved = resolve_document_path(filename)
    except ValueError as e:
        return False

    relative = os.path.relpath(resolved, BASE_DIR)
    if not verify_access_token(username, relative, token):
        return False

    os.makedirs(os.path.dirname(resolved), exist_ok=True)
    with open(resolved, 'wb') as f:
        f.write(content)
    return True


def list_documents(subdirectory: str = '') -> list:
    """List documents in a subdirectory."""
    if subdirectory:
        cleaned = sanitize_filename(subdirectory)
        if not check_path_traversal(cleaned):
            return []
        normalized = normalize_unicode(cleaned)
        target = os.path.join(BASE_DIR, normalized)
    else:
        target = BASE_DIR

    if not os.path.isdir(target):
        return []

    results = []
    for entry in os.scandir(target):
        if entry.is_file() and validate_extension(entry.name):
            results.append(entry.name)
    return results
